// Embedding gorm.Model adds ID/CreatedAt/UpdatedAt/DeletedAt.
type User struct {
	gorm.Model            // ID uint, timestamps, DeletedAt (soft delete)
	Name  string `gorm:"size:100;not null"`
	Email string `gorm:"uniqueIndex"`         // unique index on email
	Age   uint8  `gorm:"default:18"`
	Posts []Post                              // has-many association
}

type Post struct {
	gorm.Model
	Title  string
	UserID uint // foreign key back to User (Belongs To)
}

// Table name inferred: User -> "users", Post -> "posts".

// Open builds the pool; AutoMigrate reconciles schema with structs.
dsn := "host=localhost user=app password=secret dbname=app port=5432 sslmode=disable"
db, err := gorm.Open(postgres.Open(dsn), &gorm.Config{})
if err != nil {
	log.Fatalf("open: %v", err)
}

// Creates users/posts tables + columns + indexes; additive, safe to re-run.
if err := db.AutoMigrate(&User{}, &Post{}); err != nil {
	log.Fatalf("migrate: %v", err)
}
// db is shared by every goroutine for the life of the process.

// Create back-fills the PK; First/Find read; Updates writes; Delete soft-deletes.
user := User{Name: "Alice", Email: "a@x.io"}
db.Create(&user)                 // INSERT ... RETURNING id; user.ID now set

var found User
db.First(&found, user.ID)        // SELECT ... WHERE id = ? ORDER BY id LIMIT 1

var adults []User
db.Where("age >= ?", 18).Find(&adults) // SELECT ... WHERE age >= 18

db.Model(&found).Updates(User{Name: "Alicia"}) // UPDATE users SET name=...
db.Delete(&found)                // soft delete: UPDATE ... SET deleted_at = now()
// db.Unscoped().Delete(&found) would issue a real DELETE.

// Many2Many uses a join table; Has Many uses a foreign key column.
type User struct {
	gorm.Model
	Name  string
	Posts []Post                                     // has many
	Roles []Role `gorm:"many2many:user_roles;"`       // many-to-many join table
}
type Role struct {
	gorm.Model
	Name string
}

// Creating a user with nested posts inserts both in one transaction.
db.Create(&User{
	Name:  "Bob",
	Posts: []Post{{Title: "Hello"}, {Title: "World"}}, // auto-set UserID
})
// user_roles(user_id, role_id) rows are created when Roles are associated.

// BAD: N+1 — one query for users, then one per user for posts.
var users []User
db.Find(&users)
for _, u := range users {
	db.Model(&u).Association("Posts").Find(&u.Posts) // +1 query each!
}

// GOOD: Preload eager-loads all posts in ONE extra batched query.
var preloaded []User
db.Preload("Posts").Find(&preloaded)
// SQL: SELECT * FROM users;  SELECT * FROM posts WHERE user_id IN (1,2,3,...)

// For a belongs-to, Joins folds it into a single query:
var posts []Post
db.Joins("User").Find(&posts) // SELECT ... FROM posts JOIN users ON ...

// Transaction closure: commit on nil, auto-rollback on error/panic.
err := db.Transaction(func(tx *gorm.DB) error {
	if err := tx.Create(&User{Name: "Carol"}).Error; err != nil {
		return err // triggers ROLLBACK
	}
	return tx.Exec("UPDATE stats SET users = users + 1").Error
}) // COMMIT if err == nil

// Hook: runs automatically before every INSERT of a User.
func (u *User) BeforeCreate(tx *gorm.DB) error {
	if u.Name == "" {
		return errors.New("name required")
	}
	return nil
}

// Raw escape hatch with safe parameter binding.
var count int64
db.Raw("SELECT count(*) FROM users WHERE age > ?", 21).Scan(&count)

