package main

import (
	"log"

	"gorm.io/driver/postgres"
	"gorm.io/gorm"
)

type User struct {
	gorm.Model        // ID, CreatedAt, UpdatedAt, DeletedAt (soft delete)
	Name  string `gorm:"size:100;not null"`
	Email string `gorm:"uniqueIndex"`
	Age   uint8
}

func main() {
	dsn := "host=localhost user=app password=secret dbname=app port=5432 sslmode=disable"
	db, err := gorm.Open(postgres.Open(dsn), &gorm.Config{})
	if err != nil {
		log.Fatalf("open: %v", err)
	}
	if err := db.AutoMigrate(&User{}); err != nil { // additive, safe to re-run
		log.Fatalf("migrate: %v", err)
	}

	u := User{Name: "Alice", Email: "a@x.io", Age: 30}
	db.Create(&u)                 // INSERT; u.ID now populated
	log.Printf("created id=%d", u.ID)

	var got User
	db.First(&got, u.ID)          // SELECT ... WHERE id = ? LIMIT 1
	db.Model(&got).Updates(User{Name: "Alicia"}) // updates name only
	db.Delete(&got)               // soft delete: sets deleted_at
}

