func listUsers(db *gorm.DB) {
	// GOOD: one query for users + ONE batched query for all posts.
	var users []User
	db.Preload("Posts").Find(&users)
	// SQL: SELECT * FROM users;
	//      SELECT * FROM posts WHERE user_id IN (1,2,3,...);
	for _, u := range users {
		fmt.Printf("%s has %d posts\n", u.Name, len(u.Posts))
	}

	// BAD (for contrast): the loop below would issue +1 query per user.
	// for _, u := range users { db.Model(&u).Association("Posts").Find(&u.Posts) }
}

