import "gorm.io/gorm"

type User struct {
	gorm.Model
	Name   string
	Active bool
}

// BUG: struct Updates skips zero-values, so Active=false is NEVER written.
func deactivate(db *gorm.DB, id uint) error {
	return db.Model(&User{}).
		Where("id = ?", id).
		Updates(User{Active: false}). // false == zero value -> skipped!
		Error
}

