package solution

import "gorm.io/gorm"

type User struct {
	gorm.Model
	Name  string
	Posts []Post
}
type Post struct {
	gorm.Model
	Title  string
	UserID uint
}

// UsersWithPosts eager-loads Posts in a single batched query via Preload.
func UsersWithPosts(db *gorm.DB) ([]User, error) {
	var users []User
	// Query 1: SELECT * FROM users
	// Query 2: SELECT * FROM posts WHERE user_id IN (<all ids>)
	err := db.Preload("Posts").Find(&users).Error
	if err != nil {
		return nil, err
	}
	return users, nil
}

