package solution

import (
	"testing"

	"gorm.io/driver/sqlite"
	"gorm.io/gorm"
)

func setup(t *testing.T) *gorm.DB {
	db, err := gorm.Open(sqlite.Open(":memory:"), &gorm.Config{})
	if err != nil {
		t.Fatalf("open: %v", err)
	}
	if err := db.AutoMigrate(&User{}, &Post{}); err != nil {
		t.Fatalf("migrate: %v", err)
	}
	db.Create(&User{Name: "Alice", Posts: []Post{{Title: "a"}, {Title: "b"}}})
	db.Create(&User{Name: "Bob"})
	return db
}

func TestUsersWithPosts(t *testing.T) {
	db := setup(t)
	users, err := UsersWithPosts(db)
	if err != nil {
		t.Fatalf("err: %v", err)
	}
	if len(users) != 2 {
		t.Fatalf("want 2 users, got %d", len(users))
	}
	var total int
	for _, u := range users {
		total += len(u.Posts)
	}
	if total != 2 {
		t.Fatalf("want 2 posts preloaded, got %d", total)
	}
}

