package solution

import "gorm.io/gorm"

type User struct {
	gorm.Model
	Name string
}
type Post struct {
	gorm.Model
	Title  string
	UserID uint
}

// CreateUserWithPost commits both inserts or rolls back on any error.
func CreateUserWithPost(db *gorm.DB, name, title string) error {
	return db.Transaction(func(tx *gorm.DB) error {
		u := User{Name: name}
		if err := tx.Create(&u).Error; err != nil {
			return err // ROLLBACK
		}
		p := Post{Title: title, UserID: u.ID} // use the back-filled PK
		if err := tx.Create(&p).Error; err != nil {
			return err // ROLLBACK the user too
		}
		return nil // COMMIT both
	})
}

