func deactivate(db *gorm.DB, id uint) error {
	// Map form writes every listed column, including zero-values.
	return db.Model(&User{}).
		Where("id = ?", id).
		Updates(map[string]interface{}{"active": false}).
		Error
	// Equivalent: .Select("active").Updates(User{Active: false})
}

type UserCount struct {
	UserID uint
	Name   string
	Posts  int64
}

func TopUsersByPostCount(db *gorm.DB, limit int) ([]UserCount, error) {
	var out []UserCount
	// Raw escape hatch: ? is safely bound, never string-concatenated.
	err := db.Raw(`
		SELECT u.id AS user_id, u.name AS name, COUNT(p.id) AS posts
		FROM users u
		LEFT JOIN posts p ON p.user_id = u.id AND p.deleted_at IS NULL
		WHERE u.deleted_at IS NULL
		GROUP BY u.id, u.name
		ORDER BY posts DESC
		LIMIT ?`, limit).Scan(&out).Error
	if err != nil {
		return nil, err
	}
	return out, nil
}

func UpsertUserActive(db *gorm.DB, id uint, active bool) error {
	// Map form guarantees the column is written even when active == false.
	res := db.Model(&User{}).
		Where("id = ?", id).
		Updates(map[string]interface{}{"active": active})
	if res.Error != nil {
		return res.Error
	}
	if res.RowsAffected == 0 {
		return gorm.ErrRecordNotFound // no user with that id
	}
	return nil
}
